#!/usr/bin/env node
/**
 * Fix broken YAML frontmatter in blog posts generated by the CMO script.
 * Common issues:
 *   - Unquoted colons in title/description fields
 *   - Missing frontmatter entirely
 *   - Empty files
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const BLOG_DIR = path.resolve(__dirname, '../src/blog');

const files = fs.readdirSync(BLOG_DIR).filter(f => f.endsWith('.md'));
let fixed = 0;
let skipped = 0;
let deleted = 0;

for (const file of files) {
    const filePath = path.join(BLOG_DIR, file);
    const stat = fs.statSync(filePath);
    
    // Delete empty files
    if (stat.size === 0) {
        fs.unlinkSync(filePath);
        console.log(`🗑️  Deleted empty file: ${file}`);
        deleted++;
        continue;
    }

    let content = fs.readFileSync(filePath, 'utf8');
    
    // Skip non-frontmatter files (like blog.json, index.njk, feed.njk)
    if (!content.startsWith('---')) {
        skipped++;
        continue;
    }

    const fmEnd = content.indexOf('---', 3);
    if (fmEnd === -1) {
        skipped++;
        continue;
    }

    let frontmatter = content.slice(3, fmEnd);
    const body = content.slice(fmEnd);
    let changed = false;

    // Fix unquoted title and description lines containing colons
    const lines = frontmatter.split('\n');
    const fixedLines = lines.map(line => {
        // Match lines like: title: Something: With Colons
        const match = line.match(/^(title|description):\s*(.+)$/);
        if (match) {
            const key = match[1];
            let value = match[2].trim();
            // If value contains a colon and is NOT already quoted
            if (value.includes(':') && !value.startsWith('"') && !value.startsWith("'")) {
                // Escape any internal double quotes
                value = value.replace(/"/g, '\\"');
                changed = true;
                return `${key}: "${value}"`;
            }
        }
        return line;
    });

    if (changed) {
        frontmatter = fixedLines.join('\n');
        content = '---' + frontmatter + body;
        fs.writeFileSync(filePath, content);
        console.log(`✅ Fixed YAML: ${file}`);
        fixed++;
    }
}

// Now also handle files that start with ``` (code-fenced frontmatter from Gemini)
for (const file of files) {
    const filePath = path.join(BLOG_DIR, file);
    if (!fs.existsSync(filePath)) continue;
    
    let content = fs.readFileSync(filePath, 'utf8');
    
    if (content.startsWith('```markdown')) {
        content = content.replace(/^```markdown\s*\n/, '').replace(/\n```\s*$/, '');
        fs.writeFileSync(filePath, content);
        console.log(`✅ Stripped code fence: ${file}`);
        fixed++;
    } else if (content.startsWith('```')) {
        content = content.replace(/^```\s*\n/, '').replace(/\n```\s*$/, '');
        fs.writeFileSync(filePath, content);
        console.log(`✅ Stripped code fence: ${file}`);
        fixed++;
    }
}

console.log(`\n📊 Results: ${fixed} fixed, ${deleted} deleted, ${skipped} skipped`);
